func ValidResourceName(value string) bool {
	if len(value) == 0 || len(value) > MaxResourceNameBytes || !utf8.ValidString(value) {
		return false
	}
	for _, r := range value {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '.' && r != '_' && r != '-' {
			return false
		}
	}
	return true
}

